<script setup lang="ts">
import {ref,watch} from 'vue'
interface Source { title:string;url:string;type:string }
interface Target {id:string;name:string;lat:number;lon_east:number;coordinate_status:string;evidence:string;depth_m:number|null;minimum_depth_m?:number;inner_width_m:number[];depth_note:string;distance_from_selected_roi_km?:number;sources:string[]}
interface Site {id:string;name:string;country:string;admin1:string;lat:number;lon:number;coordinate_status:string;distance_km:number;rank:number;description:string;access:string;reported_length_m:number|null;length_note:string;documented_astronaut_training:boolean;task_evidence:Record<string,string[]>;sources:string[];featured_vietnam?:boolean}
interface Response {body:string;target:Target;targets:Target[];sites:Site[];sources:Record<string,Source>;ranking_rule:string;radiation_note:string;vietnam_story:string;reviewed_on:string;excluded_claims:string[]}
const props=defineProps<{body:'moon'|'mars';queryId:string;originLat:number;originLon:number;originName:string}>()
const result=ref<Response|null>(null);const busy=ref(false);const error=ref('')
const targetId=ref('');const task=ref('mapping');const sort=ref('distance')
const taskNames:Record<string,string>={mapping:'3D mapping & cave survey',geological_observation:'Volcanic geology',robotic_navigation:'Robotic navigation',communications:'Underground communications'}
let sequence=0
async function load(reset=false){
 const token=++sequence;busy.value=true;error.value=''
 if(reset)targetId.value=''
 const params=new URLSearchParams({body:props.body,user_lat:String(props.originLat),user_lon:String(props.originLon),task:task.value,sort:sort.value})
 if(props.queryId)params.set('query_id',props.queryId)
 if(targetId.value)params.set('target_id',targetId.value)
 try{const response=await fetch('/api/analogs/caves/recommend?'+params);const data=await response.json();if(token!==sequence)return;if(!response.ok)throw new Error(data.detail||'Cave recommendations unavailable');result.value=data;targetId.value=data.target.id}
 catch(e){if(token===sequence){error.value=e instanceof Error?e.message:'Cave recommendations unavailable';result.value=null}}
 finally{if(token===sequence)busy.value=false}
}
watch(()=>[props.body,props.queryId,props.originLat,props.originLon],()=>load(true),{immediate:true})
const pretty=(s:string)=>s.replace(/_/g,' ')
</script>
<template>
 <section class="base-cave-panel">
  <header><span class="base-eyebrow">Base planning · supplemental recommendation</span><h2>Caves & lava tubes</h2><p>Explore Earth training sites for subsurface survey, navigation and future habitat research.</p></header>
  <p v-if="busy" role="status">Checking documented cave evidence and calculating distances…</p>
  <p v-if="error" role="alert">{{error}}</p>
  <template v-if="result">
   <div class="cave-controls"><label>Planetary cave target<select v-model="targetId" :disabled="busy" @change="load()"><option v-for="target in result.targets" :key="target.id" :value="target.id">{{target.name}}</option></select></label><label>Training objective<select v-model="task" :disabled="busy" @change="load()"><option v-for="(name,key) in taskNames" :key="key" :value="key">{{name}}</option></select></label><label>Order suggestions<select v-model="sort" :disabled="busy" @change="load()"><option value="distance">Closest documented sites</option><option value="training_evidence">Documented space-training first</option></select></label></div>
   <article class="planetary-cave-target"><h3>{{result.target.name}}</h3><p>{{result.target.evidence}}</p><p class="pit-coordinates">{{result.target.lat.toFixed(4)}}° latitude · {{result.target.lon_east.toFixed(4)}}° east longitude</p><p>{{result.target.coordinate_status}}</p><p v-if="result.target.distance_from_selected_roi_km!=null"><strong>{{Math.round(result.target.distance_from_selected_roi_km).toLocaleString('en-US')}} km from the selected {{body==='moon'?'lunar':'Martian'}} ROI.</strong> This is a separate exploration target; it is not assumed to lie beneath your landing site.</p><dl><div><dt>Reported opening</dt><dd>{{result.target.inner_width_m[0]}}–{{result.target.inner_width_m[1]}} m</dd></div><div><dt>{{result.target.depth_m!=null?'Reported pit depth':'Published minimum depth'}}</dt><dd>{{result.target.depth_m??result.target.minimum_depth_m}} m</dd></div><div><dt>Roof thickness / shielding dose</dt><dd>Not established</dd></div></dl><small>{{result.target.depth_note}}</small><div class="cave-sources"><a v-for="id in result.target.sources" :key="id" :href="result.sources[id].url" target="_blank" rel="noopener">{{result.sources[id].title}} ↗</a></div></article>
   <aside class="cave-radiation-note"><strong>Potential shelter is a research question</strong><p>{{result.radiation_note}} Earth cave work trains exploration methods; it does not reproduce lunar or Martian radiation.</p></aside>
   <h3>Earth field-research suggestions</h3><p class="cave-ranking-note">Only sites with a documented lava tube and a cited record for <strong>{{taskNames[task]}}</strong> are included. {{sort==='distance'?'Ordered by great-circle distance from '+originName+'.':'Published astronaut-training campaigns first, then distance.'}} This is separate from the surface Top-5 score.</p>
   <p v-if="!result.sites.length">No documented site supports this objective in the current evidence catalog.</p>
   <article v-for="site in result.sites" :key="site.id" class="earth-cave-site" :class="{'vietnam-highlight':site.featured_vietnam}">
    <div class="cave-site-heading"><div><span v-if="site.featured_vietnam" class="vietnam-badge">Vietnam field-research spotlight</span><h3>#{{site.rank}} {{site.name}}</h3><small>{{site.admin1}}, {{site.country}}</small></div><strong>{{Math.round(site.distance_km).toLocaleString('en-US')}} km<small>from {{originName}}</small></strong></div>
    <p>{{site.description}}</p><div class="cave-capabilities"><span v-for="key in Object.keys(site.task_evidence)" :key="key">{{taskNames[key]??pretty(key)}}</span></div>
    <dl><div><dt>Space-training record</dt><dd>{{site.documented_astronaut_training?'Published astronaut / analogue campaign':'No documented astronaut campaign in these sources'}}</dd></div><div v-if="site.reported_length_m!=null"><dt>Reported survey length</dt><dd>{{site.reported_length_m.toLocaleString('en-US')}} m · historic baseline</dd></div><div><dt>Planning coordinates</dt><dd>{{site.lat.toFixed(5)}}°, {{site.lon.toFixed(5)}}°</dd></div></dl>
    <p v-if="site.reported_length_m!=null" class="cave-small">{{site.length_note}}</p><p class="cave-small">{{site.coordinate_status}} · <a :href="`https://www.google.com/maps/search/?api=1&query=${site.lat},${site.lon}`" target="_blank" rel="noopener">View planning location ↗</a></p><p class="cave-access"><strong>Research access:</strong> {{site.access}}</p>
    <div class="cave-sources"><a v-for="id in site.sources" :key="id" :href="result.sources[id].url" target="_blank" rel="noopener">{{result.sources[id].title}} ↗</a></div>
   </article>
   <details class="cave-method"><summary>How these suggestions were produced</summary><p>{{result.ranking_rule}}</p><p>No similarity percentage, underground DEM, radiation dose or formation age is invented to fill missing fields. Distances use spherical great-circle geometry; reference coordinates have the precision stated above.</p><ul><li v-for="claim in result.excluded_claims" :key="claim">{{claim}}</li></ul><p>Evidence reviewed: {{result.reviewed_on}}. Current research access must be confirmed with the site authority.</p></details>
  </template>
 </section>
</template>
<style scoped>
.base-cave-panel{color:#0f172a;font-size:14px;line-height:1.6}.base-eyebrow{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#64748b}.base-cave-panel h2{font-size:26px;margin:6px 0}.base-cave-panel h3{font-size:17px;margin:4px 0 10px}.base-cave-panel header p{margin:0;color:#475569}.cave-controls{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:22px 0}.cave-controls label:first-child{grid-column:1/-1}.cave-controls label{display:grid;gap:6px;font-size:12px}.cave-controls select{font:inherit;min-width:0;padding:10px;border:1px solid #cbd5e1;background:white;border-radius:8px}.planetary-cave-target{padding:18px;background:#f1f5f9;border:1px solid #cbd5e1;border-radius:12px}.pit-coordinates{font-variant-numeric:tabular-nums}.base-cave-panel dl{margin:12px 0}.base-cave-panel dl>div{display:flex;justify-content:space-between;gap:16px;padding:9px 0;border-bottom:1px solid #e2e8f0}.base-cave-panel dt{color:#64748b}.base-cave-panel dd{margin:0;text-align:right;max-width:60%}.base-cave-panel small,.cave-small{font-size:11px;color:#64748b}.cave-sources{display:grid;gap:6px;margin-top:12px}.cave-sources a{font-size:11px;color:#1d4ed8;text-decoration:underline;overflow-wrap:anywhere}.cave-radiation-note{padding:14px;border:1px solid #e8d7a9;border-radius:10px;background:#fffbeb;margin:16px 0 24px}.cave-radiation-note p{margin-bottom:0;font-size:12px}.cave-ranking-note{font-size:12px;color:#475569}.earth-cave-site{border:1px solid #cbd5e1;border-radius:12px;padding:18px;margin:14px 0;background:white}.vietnam-highlight{border-color:#86a78b;background:#f8fbf6}.cave-site-heading{display:flex;justify-content:space-between;align-items:start;gap:16px}.cave-site-heading>strong{white-space:nowrap;text-align:right;font-size:18px}.cave-site-heading>strong small{display:block;font-size:11px;font-weight:normal;white-space:normal}.vietnam-badge{font-size:10px;color:#166534;text-transform:uppercase;letter-spacing:.05em}.cave-capabilities{display:flex;flex-wrap:wrap;gap:6px}.cave-capabilities span{font-size:11px;background:#eff6ff;color:#1e40af;padding:4px 7px;border-radius:5px}.cave-access{font-size:12px;background:#f8fafc;padding:10px;border-radius:6px}.cave-method{font-size:12px;color:#475569;margin:22px 0}.cave-method summary{cursor:pointer;font-weight:600}@media(max-width:600px){.cave-controls{grid-template-columns:1fr}.cave-site-heading{flex-wrap:wrap}.base-cave-panel dl>div{display:block}.base-cave-panel dd{text-align:left;max-width:none}}
</style>
